head.script:
scwin.onpageload = function() {
	requires("uiplugin.popup");

	dataList1.insertRow();
};

scwin.btn_wframePopup1_onclick = function(e) {
var jsnPopupData = {
    "type" : "json", // 데이터 유형. "json"을 권장
    "name" : "exam_param",  // 데이터를 가져오기 위한 파라미터 이름으로 팝업 화면에서 $p.getParameter("exam_param")로 추출할 수 있음
    "data" : { 
        "Personal Info" : { "Name": "Lee", "Age": 50, "Married" : false}, 
        "Region": "Seoul"
    } // 실제 전달할 데이터
};


var opt = {
 id : 'popupTest01',
  popupName : 'test',
  type : 'wframePopup',
  width : '500px',
  height : '700px',
  top : '140px',
  left : '500px',
  modal : true,
  alwaysOnTop : false,
  useModalStack : true,
  resizable : true,
  useMaximize : false,
  className : "",
  scrollbars : true,
  disableCloseButton : false,
  dataObject : jsnPopupData,
  accessibility : true
  };
	$p.openPopup("openPopup_wframePopup_accessibility_WESE-1099_(WSQ-6028)_popup.xml", opt);
};

scwin.btn_wframePopup2_onclick = function(e) {
var jsnPopupData = {
    "type" : "json", // 데이터 유형. "json"을 권장
    "name" : "exam_param",  // 데이터를 가져오기 위한 파라미터 이름으로 팝업 화면에서 $p.getParameter("exam_param")로 추출할 수 있음
    "data" : { 
        "Personal Info" : { "Name": "Lee", "Age": 50, "Married" : false}, 
        "Region": "Seoul"
    } // 실제 전달할 데이터
};


var opt = {
 id : 'popupTest01',
  popupName : 'test',
  type : 'wframePopup',
  width : '500px',
  height : '700px',
  top : '140px',
  left : '500px',
  modal : true,
  alwaysOnTop : false,
  useModalStack : true,
  resizable : true,
  useMaximize : false,
  className : "",
  scrollbars : true,
  disableCloseButton : false,
  dataObject : jsnPopupData,
  accessibility : false
  };
    $p.openPopup("openPopup_wframePopup_accessibility_WESE-1099_(WSQ-6028)_popup.xml", opt);
};


	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById("popupTest01_wframe_ipx_name").classList.contains("w2input_focus");
	}

	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_wframePopup1').click()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()","true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
        }
	scwin.unitTest()
